  ?zone a brick:Zone ; rdfs:label "Basement" .
  ?point brick:isPointOf ?zone ;
         a brick:Occupancy .
  ?point ref:hasExternalReference ?ext ; ref:hasTimeseriesId ?tsid .
}

SELECT ?s WHERE {
  ?s brick:hasProperty [ a brick:Occupancy ] .
}
LIMIT 10

SELECT ?point ?pc ?tsid ?label WHERE {
  ?z rdfs:label "Basement" .
  ?point brick:isPointOf ?z .
  ?point a ?pc .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
  OPTIONAL { ?point rdfs:label ?label . }
}

